'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { makeRnd } = require('./data');
const { BudgetExceeded, Ops, counted, countedFn } = require('./counting');
const { basketTotal } = require('../src/pricing.js');

const PRICE = (k) => String(k).length * 7 + (String(k).charCodeAt(0) % 13);

function oracle(a, b) {
  return a.reduce((t, [k, q]) => t + b(k) * q, 0);
}

function clone(args) {
  return args.map((x) => (Array.isArray(x) ? x.map((y) => (typeof y === 'object' && y !== null ? JSON.parse(JSON.stringify(y)) : y)) : x));
}

function smallArgs(rnd) {
  return [Array.from({ length: rnd(15) }, () => [rnd(6), 1 + rnd(4)]), PRICE];
}
function wrapArgs(a, b) {
  return [a, countedFn(b)];
}

test('matches the reference on random inputs', () => {
  const rnd = makeRnd(500);
  for (let i = 0; i < 120; i++) {
    const args = smallArgs(rnd);
    assert.deepStrictEqual(basketTotal(...clone(args)), oracle(...clone(args)));
  }
});

test('works with instrumented inputs', () => {
  const rnd = makeRnd(501);
  for (let i = 0; i < 40; i++) {
    const args = smallArgs(rnd);
    assert.deepStrictEqual(basketTotal(...wrapArgs(...clone(args))), oracle(...clone(args)));
  }
});

test('empty inputs', () => {
  const args = [[], PRICE];
  assert.deepStrictEqual(basketTotal(...clone(args)), oracle(...clone(args)));
});

