'use strict';

function basketTotal(lines, priceOf) {
  const cache = new Map();
  let total = 0;
  for (const [key, qty] of lines) {
    if (!cache.has(key)) cache.set(key, priceOf(key));
    total += cache.get(key) * qty;
  }
  return total;
}

module.exports = { basketTotal };

