'use strict';

function rollingLoad(samples, span) {
  const data = Array.from(samples);
  const out = [];
  let total = 0;
  for (let i = 0; i < data.length; i++) {
    total += data[i];
    if (i >= span) total -= data[i - span];
    if (i >= span - 1) out.push(Math.floor(total / span));
  }
  return out;
}

module.exports = { rollingLoad };

