function rollingLoad(samples, span) {
  const out = [];
  for (let start = 0; start + span <= samples.length; start++) {
    const window = samples.slice(start, start + span);
    out.push(Math.floor(window.reduce((x, y) => x + y, 0) / span));
  }
  return out;
}

module.exports = { rollingLoad };

