'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { makeRnd } = require('./data');
const { BudgetExceeded, Ops, counted, countedFn } = require('./counting');
const { kitPrice } = require('../src/joblab.js');

function makeCatalog(rnd, n) {
  const rows = new Map();
  for (let i = 0; i < n; i++) {
    if (i >= n - 3) { rows.set(i, [1 + rnd(8), []]); continue; }
    const parts = new Set();
    for (let k = 0; k < 2; k++) parts.add(i + 1 + rnd(Math.min(n, i + 4) - i - 1));
    rows.set(i, [1 + rnd(8), [...parts].sort((x, y) => x - y).map((p) => [p, 1 + rnd(2)])]);
  }
  return (item) => rows.get(item);
}

function oracle(a, b) {
  const known = new Map();
  const cost = (item) => {
    if (!known.has(item)) {
      const [unit, parts] = b(item);
      let total = unit;
      for (const [part, qty] of parts) total += qty * cost(part);
      known.set(item, total);
    }
    return known.get(item);
  };
  return cost(a);
}

function clone(args) {
  return args.map((x) => (Array.isArray(x) ? x.map((y) => (typeof y === 'object' && y !== null ? JSON.parse(JSON.stringify(y)) : y)) : x));
}

function smallArgs(rnd) {
  return [0, makeCatalog(rnd, 1 + rnd(9))];
}
function wrapArgs(a, b) {
  return [a, countedFn(b)];
}

test('matches the reference on random inputs', () => {
  const rnd = makeRnd(503);
  for (let i = 0; i < 120; i++) {
    const args = smallArgs(rnd);
    assert.deepStrictEqual(kitPrice(...clone(args)), oracle(...clone(args)));
  }
});

test('works with instrumented inputs', () => {
  const rnd = makeRnd(504);
  for (let i = 0; i < 40; i++) {
    const args = smallArgs(rnd);
    assert.deepStrictEqual(kitPrice(...wrapArgs(...clone(args))), oracle(...clone(args)));
  }
});

test('empty inputs', () => {
  const args = [0, makeCatalog(makeRnd(0), 1)];
  assert.deepStrictEqual(kitPrice(...clone(args)), oracle(...clone(args)));
});

