    has(t, p) { if (isIndex(p)) tick(); return Reflect.has(t, p); },
    deleteProperty(t, p) { if (isIndex(p)) tick(); return Reflect.deleteProperty(t, p); },
  });
}

function countedFn(fn) {
  return (...args) => { tick(); return fn(...args); };
}

