'use strict';

function threadDepths(comments, replyTo) {
  const known = new Map();
  const depthOf = (node) => {
    if (!known.has(node)) {
      const p = replyTo(node);
      known.set(node, p === null ? 0 : depthOf(p) + 1);
    }
    return known.get(node);
  };
  return comments.map(depthOf);
}

module.exports = { threadDepths };

