'use strict';

function stepTrend(counts, days) {
  const data = Array.from(counts);
  const out = [];
  let total = 0;
  for (let i = 0; i < data.length; i++) {
    total += data[i];
    if (i >= days) total -= data[i - days];
    if (i >= days - 1) out.push(Math.floor(total / days));
  }
  return out;
}

module.exports = { stepTrend };

