function stepTrend(counts, days) {
  const out = [];
  for (let start = 0; start + days <= counts.length; start++) {
    const window = counts.slice(start, start + days);
    out.push(Math.floor(window.reduce((x, y) => x + y, 0) / days));
  }
  return out;
}

module.exports = { stepTrend };

