'use strict';

function rainTotals(rainMm, periods) {
  const prefix = [0];
  for (let i = 0; i < rainMm.length; i++) prefix.push(prefix[i] + rainMm[i]);
  return periods.map(([lo, hi]) => prefix[hi] - prefix[lo]);
}

module.exports = { rainTotals };

